"""Register conventions for code generated by lc2kcc (provisional).

r0 is never written by generated code, so it always reads as 0. Returns
use `jalr 7 6` rather than `jump 7` (= `jalr 7 0`), which would write the
return address into r0.

The stack grows upward from the `Stack` label at the end of the image.
"""

ZERO = 0  # always 0
RV = 1  # return value
T0, T1, T2 = 2, 3, 4  # caller-saved temporaries
SP = 5  # stack pointer
AT = 6  # scratch: call targets, discarded links
RA = 7  # return address
